#nullable enable

public class UserService
{
    // Non-null parameter — passing null warns at the call site (CS8625)
    public User GetOrCreate(string email)
    {
        var user = _repo.Find(email);
        return user ?? new User(email);         // return type User — never null, compiler verified
    }

    // Nullable return — callers MUST check (CS8603 if they don't)
    public User? Find(string id) => _repo.Find(id);

    public string Describe(string? nickname)   // null is part of the contract
    {
        if (nickname is null) return "anonymous";   // compiler learns from the check
        return nickname.Trim();                       // no CS8602 — flow analysis proved non-null
    }

    // Null-forgiving for framework-filled members (constructor injection, EF)
    private readonly AppDbContext _db = null!;   // DI assigns before first use

    public bool TryGetDefault(string id, [NotNullWhen(true)] out User? user)
    {
        user = _repo.Find(id);
        return user is not null;                 // the attribute tells callers:
    }                                            // if true, user is non-null — no warning
}

